async function setFeelEnabled(enabled,{announce=true}={}){feelEnabled=enabled;$('feel-toggle').setAttribute('aria-pressed',String(enabled));$('feel-toggle').textContent=enabled?'ON':'TURN ON';$('feel-match').classList.toggle('enabled',enabled);try{localStorage.setItem('btr-feel-match',enabled?'on':'off');}catch{}if(enabled){if(announce){const context=createAudio();if(context?.state==='suspended')await context.resume();}setFeelStatus('FEEL THE MATCH IS ON','Live cues use reached events only. Choose a cue below to learn the pattern.');if(announce)speak('Feel the Match is on. Live cues use reached events only.');}else{window.speechSynthesis?.cancel();setFeelStatus('READY TO PREVIEW','Off until you choose to enable sound and vibration.');}}

function renderRecap(preset){const config={player:['player',cue.language||'en'],tactical:['analyst',cue.language||'en'],beginner:['beginner',cue.language||'en'],disputed:['analyst',cue.language||'en'],spanish20:['fan','es']}[preset]||['analyst',cue.language||'en'],target=storyFor(config[0],config[1]),player=target.brief?.player?.name||'Selected player';currentRecap=buildPerspectiveRecap({preset,story:target,alternateStory:target,focusName:player,corrected:challenged||target.revision===2});$('recap-output').hidden=false;$('recap-output-title').textContent=currentRecap.title;$('recap-status').textContent=`${currentRecap.target_duration_s} SEC · ${currentRecap.language.toUpperCase()} · ${currentRecap.correction_status.toUpperCase()}`;$('recap-scenes').replaceChildren(...currentRecap.entries.map(entry=>{const li=document.createElement('li'),time=document.createElement('time'),copy=document.createElement('div'),title=document.createElement('b'),narration=document.createElement('p'),sources=document.createElement('small');time.textContent=`${Math.floor(entry.timestamp_s/60)}:${String(Math.floor(entry.timestamp_s%60)).padStart(2,'0')}`;title.textContent=entry.overlay;narration.textContent=entry.narration;sources.textContent=entry.evidence_ids.length?`SOURCE · ${entry.evidence_ids.join(' · ')}`:'NO MATCHING REACHED SOURCE';copy.append(title,narration,sources);li.append(time,copy);return li;}));$('recap-limit').textContent=currentRecap.limitations.join(' ');document.querySelectorAll('[data-recap-preset]').forEach(button=>button.classList.toggle('active',button.dataset.recapPreset===preset));$('recap-output').scrollIntoView({behavior:'smooth',block:'nearest'});}
function downloadRecap(){if(!currentRecap)return;const blob=new Blob([JSON.stringify(currentRecap,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`btr-${currentRecap.preset}-recap.json`;link.click();URL.revokeObjectURL(url);}

document.querySelectorAll('.mode-rack button').forEach(button=>button.onclick=()=>{mode=button.dataset.mode;render();document.querySelectorAll('.mode-rack button em').forEach(label=>label.textContent='Choose view ↗');button.querySelector('em').textContent='Selected ✓';toast(`${button.querySelector('b').textContent} is now your live view.`);if(navigator.vibrate)navigator.vibrate(10);});
