$('challenge').onclick=()=>{challenged=!challenged;$('challenge').classList.toggle('active',challenged);$('challenge').firstChild.textContent=challenged?'RESTORE RECORDED EVIDENCE ':'CHANGE THE EVIDENCE ';const result=$('change-result');result.hidden=!challenged;if(challenged){const meaningful=cue.source==='match'&&cue.source_id==='wide'&&cue.cutoff>=16;result.innerHTML=meaningful?'<b>SIMULATION · CLAIM WITHDRAWN</b>The defender now holds position. The run and completed passes remain recorded, but the claim that the run moved the defender no longer survives.':'<b>SIMULATION · LIMIT ADDED</b>The changed assumption is separated from the recorded play. Any tactical conclusion depending on it must be withheld.';}render();if(challenged)announceSignals([{kind:'correction'}]);};
$('ask-form').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(q){$('question').value='';ask(q);}};document.querySelectorAll('.quick-asks button').forEach(b=>b.onclick=()=>ask(b.textContent));
$('voice').onclick=()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice input is not available in this browser.');return;}const r=new SpeechRecognition();r.lang={en:'en-US',es:'es-ES',pt:'pt-BR'}[cue?.language]||'en-US';r.interimResults=false;$('voice').textContent='●';r.onresult=e=>{$('question').value=e.results[0][0].transcript;$('question').focus();};r.onerror=()=>toast('I could not hear that. Try typing your question.');r.onend=()=>$('voice').textContent='⌁';r.start();};
document.querySelectorAll('.dock [data-screen-target]').forEach(button=>button.onclick=()=>showScreen(button.dataset.screenTarget));
document.querySelectorAll('[data-open-screen]').forEach(button=>button.onclick=()=>showScreen(button.dataset.openScreen));
document.querySelectorAll('[data-mode-pick]').forEach(button=>button.onclick=()=>{mode=button.dataset.modePick;render();showScreen('live');toast('Player Focus is now following Luca Moreau.');});
$('focus-toggle').onclick=()=>showScreen('players');
document.querySelector('.favorite').onclick=event=>{event.currentTarget.classList.toggle('active');event.currentTarget.textContent=event.currentTarget.classList.contains('active')?'♥':'♡';toast(event.currentTarget.classList.contains('active')?'Player added to your match.':'Player removed from favorites.');};

$('director-expand').onclick=()=>{const expanded=document.body.classList.toggle('director-expanded');$('director-expand').setAttribute('aria-expanded',String(expanded));$('director-expand').textContent=expanded?'LESS −':'MORE +';};
$('data-expand').onclick=()=>{const expanded=document.body.classList.toggle('data-expanded');$('data-expand').setAttribute('aria-expanded',String(expanded));$('data-expand').textContent=expanded?'CLOSE −':'OPEN +';};
$('feel-toggle').onclick=()=>setFeelEnabled(!feelEnabled);
document.querySelectorAll('[data-cue-preview]').forEach(button=>button.onclick=async()=>{if(!feelEnabled)await setFeelEnabled(true);emitSignal({kind:button.dataset.cuePreview,team:'harbor'},{preview:true});});
document.querySelectorAll('[data-recap-preset]').forEach(button=>button.onclick=()=>renderRecap(button.dataset.recapPreset));
$('play-recap').onclick=()=>{if(!currentRecap)return;speak(currentRecap.entries.map(entry=>entry.narration).join(' '),currentRecap.language);};
$('download-recap').onclick=downloadRecap;

$('stay-awake').onclick=async()=>{if(!('wakeLock'in navigator)){toast('Screen-awake mode is not available in this browser.');return;}try{if(wakeLock){await wakeLock.release();wakeLock=null;$('stay-awake').classList.remove('active');toast('Screen-awake mode is off.');}else{wakeLock=await navigator.wakeLock.request('screen');$('stay-awake').classList.add('active');wakeLock.addEventListener('release',()=>{$('stay-awake').classList.remove('active');wakeLock=null;},{once:true});toast('Pocket Director will stay awake during the match.');}}catch{toast('Your phone could not enable screen-awake mode.');}};
$('share-moment').onclick=async()=>{const story=activeStory(),data={title:`BTR · ${story.title||cue.title}`,text:`${story.body||cue.body}\n\nSynthetic evidence through ${story.clock||cue.clock}.`,url:location.href};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(`${data.title}\n${data.text}\n${data.url}`);toast('Moment copied to your clipboard.');}}catch(error){if(error.name!=='AbortError')toast('This moment could not be shared.');}};
const pip=$('picture-in-picture');if(!document.pictureInPictureEnabled||!$('hero-film').requestPictureInPicture)pip.disabled=true;pip.onclick=async()=>{try{if(document.pictureInPictureElement)await document.exitPictureInPicture();else await $('hero-film').requestPictureInPicture();}catch{toast('Floating video is not available right now.');}};

addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install-app').hidden=false;});
$('install-app').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install-app').hidden=true;};
addEventListener('appinstalled',()=>toast('Pocket Director is installed.'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('pocket-sw.js',{scope:'./'}).catch(()=>{});
try{if(localStorage.getItem('btr-feel-match')==='on')setFeelEnabled(true,{announce:false});}catch{}

fetch('api-config.json').then(r=>r.json()).then(c=>{base=c.baseUrl||'';return connect();}).catch(()=>{cue=demoCue();render();}).finally(()=>{const initial=params.get('screen');if(['live','perspectives','players','more'].includes(initial))showScreen(initial,{scroll:false});});
